  ('mccormick', 'salaire médian : « The annual total compensation of our median employee (other than the CEO) for 2025 was $41,468 » ; ratio calculé sur le monde entier, puis sur les seuls salariés américains : « Median Employee Globally 261:1 Median Employee in the United States 122:1 »'),
  ('kimberly-clark', 'salaire médian : « the total compensation of our median employee was $56,552 » ; rémunération totale du PDG : « the total compensation of our CEO, as reported in the Summary Compensation Table, was $15,320,405 » ; sans correction du coût de la vie : « We did not make any cost-of-living adjustments »'),
  ('monster-beverage', 'qui est le salarié médian : « the median employee was an exempt, full-time employee located in the U.S. with an annual total compensation of $88,521 for 2025 » ; rémunération totale du PDG : « annual total compensation for 2025 was $19,282,630 »'),
  ('brown-forman', 'rémunération totale du PDG : « was $25,304,882 as disclosed in the Fiscal 2026 Summary Compensation Table on page 50 » ; salaire médian : « our median employee for fiscal 2026 received annual total compensation of $57,651 in fiscal 2026 » ; périmètre : « Identified our global employee population as of February 1, 2026 »'),
  ('edgewell', 'salaire médian : « The median employee selected has a total compensation of $49,375 »'),
  ('energizer', 'rémunérations totales du PDG puis du salarié médian, en dollars : « Annual Total Compensation 10,972,516 42,325 » ; temps partiel : « whether employed on a full-time or part-time basis, was considered in determining our median employee »'),
  ('mattel', 'qui est le salarié médian : « The global median employee worked in our manufacturing facility in Malaysia » ; salariés hors des États-Unis : « Approximately 26,000 employees (85% of the total workforce) are located outside the United States » ; sans correction du coût de la vie : « No cost-of-living adjustments were made »'),
  ('hasbro', 'salaire médian : « We determined that the median employee’s total compensation (as would be computed for purposes of the Summary Compensation Table) was $113,241 » ; rémunération totale du PDG : « as shown in our Summary Compensation Table above, is $18,672,521 »'),
  ('3m', 'rémunérations totales du PDG puis du salarié médian : « the 2025 total compensation was $21,005,009 for our CEO and $66,524 for our median employee » ; sans correction du coût de la vie : « We did not apply any cost-of-living adjustments as part of the calculation »'),
  ('stanley-black-decker', 'salaire médian : « our median employee’s total annual compensation, inclusive of benefits, was an estimated $47,897 » ; salariés hors des États-Unis : « 65% of whom were located outside of the U.S. »'),
  ('post-holdings', 'salaire médian : « The annual total compensation of our median employee was $95,061 »'),
  ('spectrum-brands', 'périmètre : « we made a determination from our global employee population »'),
  ('kontoor', 'qui est le salarié médian : « our fiscal 2025 median employee was a full-time, Mexico-based production operator whose fiscal 2025 annual total compensation was $10,618 » ; répartition des salariés : « Approximately 47% of our workforce is located in Latin America and Mexico » ; sans correction du coût de la vie : « We did not make any cost-of-living adjustments »'),
  ('wd-40', 'salaire médian : « the total annual compensation for the median employee for fiscal year 2025 was calculated to be $113,343 » ; rémunération totale du PDG : « which was $4,266,899 for fiscal year 2025 » ; qui est le salarié médian : « The Company’s median employee is located in the U.S. »'),
  ('church-dwight', 'rémunérations totales du PDG puis du salarié médian : « TOTAL $ 9,799,678 $ 81,203 » ; temps partiel : « We included all employees, whether employed on a full-time or part-time basis »'),
  ('garmin', 'salaire médian : « Median employee annual total compensation: $46,356 »'),
  ('beyond-meat', 'détail : salaire, prime, actions, intéressement, autres, total (PDG puis salarié médian) : « Chief Executive Officer 587,500 1,200 26,701,431 2,500,425 56,294 29,846,850 Median Employee 63,183 — — — 2,527 65,710 » ; temps partiel : « all regular full-time and part-time employees globally »')
) as a(slug, ajout), entities en, indicators i
where en.slug = a.slug and en.id = ev.entity_id and i.id = ev.indicator_id and i.code = 'LAB_CEO_PAY_RATIO'
  and ev.source_url like '%sec.gov%' and strpos(ev.excerpt, a.ajout) = 0;
